import{z as s,x as A,o as t,c as p,q as r,j as o,D as i,d as l,s as E,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"词表裁剪","description":"","frontmatter":{"title":"词表裁剪","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/vocab-pruning.md","filePath":"llm/vocab-pruning.md","lastUpdated":1791413859000}'),m={name:"llm/vocab-pruning.md"};function B(D,a,h,g,_,f){const n=A("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="词表裁剪" tabindex="-1">词表裁剪 <a class="header-anchor" href="#词表裁剪" aria-label="Permalink to &quot;词表裁剪&quot;">​</a></h1><div class="epigraph"><p>小模型里 embedding 加 lm_head 可以占掉总参数的一大截。域适配之后，许多行从未被看见——删行必须连分词器一起删。</p><footer>—— 对照 ALBERT 的因子化嵌入；域内分词器实践见 Dagan, Synnaeve, Rozière, 2024 一类工作</footer></div><p><a href="/llm/prompt-compression">上一课</a> 减输入长度。本课减 <strong>\\(|V|\\)</strong>：embedding 与（通常绑定的）lm_head 是 \\(|V|\\times d\\)。缺口是：权重稀疏与低秩都不碰这两张表，于是 1B 级模型压缩完仍被词表拖住。<a href="/llm/vocab-scaling-law">词表规模缩放律</a> 讲过 \\(|V|\\) 与损失的交换；本课是事后裁剪，不是从零选 \\(|V|\\)。后课权重共享是另一条减参轴。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>通用词表为多语言与代码留了大量 id。垂直域上，大量 token 频率为零，对应行在微调里也几乎无梯度，却仍占显存与 lm_head 的 GEMM。直接把这些行从检查点里删掉、推理却仍用旧分词器，会把文本映到已删 id，或落到 UNK / 字节回退上，行为未定义。缺口是 <strong>tokenizer 与两张表同时改</strong>，并处理残留：旧对话里的特殊 token、工具标签、保留位。</p><p>ALBERT 用因子化嵌入 \\(E=E_1 E_2\\) 降参数，不删 id，OOV 行为不变。裁剪更狠：id 集合变小，fertility 与公平性都会变，压缩课要把它当能力风险，而不是只当存储。</p><p><span class="marginnote">绑定的 lm_head 必须与 embedding 同步删行。只瘦 embedding、头仍 \\(|V|\\)，logits 错位。Press &amp; Wolf 的 tying 在这里是约束，不是可选项。</span></p><p><span class="marginnote">fertility 可以翻译成「碎词率」：同一个词平均被切成几个 token。裁剪后保留的 token 更常见、往往更短，同样一句话要切成更多片，所以 token 数变多——这就是域内 PPL 不可横比的根源：每 token 的含义被稀释了。</span></p><p><span class="marginnote">数字实例：\\(|V|=128{,}000\\)、\\(d=2048\\) 时，一张表就是 \\(128000 \\times 2048 \\approx 2.6\\) 亿参数，embedding 加 lm_head 共约 5 亿；若总参数 1.5B，这两张表占三分之一。把 \\(|V&#39;|\\) 砍到 32k，两表立刻缩到约 1.3 亿。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>统计域语料（含模板、代码、数字）上的 token 频次，保留特殊符号与字节回退所需的字节级符号，按阈值或目标 \\(|V&#39;|\\) 丢掉长尾。重写分词器词表与合并表，使不会再产生被删 id。检查点按 id 映射收缩两行矩阵，对仍保留的行保持原向量。短校准或继续预训练，让 lm_head 在新词表上重新校准频率。</p><p>评测：域内 PPL 会因 token 变长（fertility 升）而不可比，必须用生成式任务与字节级或词级对照。跨语言若误删脚本块，会表现为突然的字节回退爆炸，而不是轻微掉点。</p>',12)),(t(),o(d,null,{default:i(()=>[E(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CORP%5B%22%E5%9F%9F%E8%AF%AD%E6%96%99%E9%A2%91%E6%AC%A1%22%5D%20--%3E%20KEEP%5B%22%E4%BF%9D%E7%95%99%E7%89%B9%E6%AE%8A%E7%AC%A6%E5%8F%B7%E4%B8%8E%E5%AD%97%E8%8A%82%22%5D%0A%20%20KEEP%20--%3E%20DROP%5B%22%E5%88%A0%E9%95%BF%E5%B0%BE%20id%22%5D%0A%20%20DROP%20--%3E%20TOK%5B%22%E9%87%8D%E5%86%99%E5%88%86%E8%AF%8D%E5%99%A8%22%5D%0A%20%20DROP%20--%3E%20MAT%5B%22%E6%94%B6%E7%BC%A9%20embedding%20%2F%20lm_head%22%5D%0A%20%20TOK%20--%3E%20ALIGN%5B%22id%20%E5%AF%B9%E9%BD%90%22%5D%0A%20%20MAT%20--%3E%20ALIGN%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"未使用行不贡献前向，删它们在域内近似无损。伤害来自边界：稀有但关键的标识符、别的语种、数字块。预分词若把数字切成单数字 token，数字 id 很热，不会被删；若整块数字是稀有合并符号，裁剪会毁掉算术——与量化课的算术崩同类，根因是符号集合。",-1)),a[5]||(a[5]=e("p",null,[e("a",{href:"/llm/lora"},"LoRA"),l(" 打在 embedding 上时，裁剪要在合并后做，或对 \\(A,B\\) 同样收缩行，否则秩分解的行维与表不一致。")],-1)),a[6]||(a[6]=e("p",null,"裁剪最容易翻车的路径是「删了表却没删分词器」：旧分词器仍会输出被删的 id，模型查不到行、也不认识这个位置，于是文本要么映到错误的保留 token，要么掉进字节回退，输出突然变成乱码式爆炸。下图画出这条事故链。",-1)),(t(),o(d,null,{default:i(()=>[E(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E5%88%86%E8%AF%8D%E5%99%A8%E4%BB%8D%E5%9C%A8%E7%94%A8%22%5D%20--%3E%20OUT%5B%22%E8%BE%93%E5%87%BA%E8%A2%AB%E5%88%A0%20id%22%5D%0A%20%20OUT%20--%3E%20LOOK%5B%22%E6%9F%A5%20embedding%20%E8%A1%8C%22%5D%0A%20%20LOOK%20--%3E%20MISS%5B%22%E8%A1%8C%E4%B8%8D%E5%AD%98%E5%9C%A8%22%5D%0A%20%20MISS%20--%3E%20A%5B%22%E8%90%BD%E5%88%B0%20UNK%22%5D%0A%20%20MISS%20--%3E%20B%5B%22%E5%AD%97%E8%8A%82%E5%9B%9E%E9%80%80%E7%88%86%E7%82%B8%22%5D%0A%20%20B%20--%3E%20GEN%5B%22%E8%BE%93%E5%87%BA%E4%B9%B1%E7%A0%81%E5%BC%8F%E9%80%80%E5%8C%96%22%5D%0A%20%20A%20--%3E%20GEN%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">常见误区：初学者容易以为「没被训练到的行删掉是无损的」。实际上删行本身近乎无损，伤害全部来自分词器与表的错位——删除动作本身安全，删除后系统两端不一致才危险。类比：辞掉公司通讯录里的离职员工没问题，但门禁卡没同步注销，他就再也进不了门。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在通用聊天模型上按单一垂直域裁词表。不要留下「保留 1000 个空位」却无 tokenizer 对应，那是未定义 id。下一课权重共享：行还在，层间或输入输出之间共用同一组参数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>词表裁剪必须同步改分词器、embedding、lm_head。</li><li>域内零频行可删；伤害在长尾关键符号与其它语种。</li><li>因子化嵌入是不删 id 的替代，OOV 行为更稳。</li><li>域内 PPL 因 fertility 变化不可横比，用生成任务验收。</li><li>出处：ALBERT 因子化嵌入；Dagan et al. 一类分词器域适配；tying 见 Press &amp; Wolf。</li></ul>',5))])}const P=s(m,[["render",B]]);export{u as __pageData,P as default};
